    'read_this_environment_s_audit_trail_who_did_what_to_wha_3e0d9fc8' => 'Čtení auditního záznamu tohoto prostředí: kdo co provedl, s jakým objektem a kdy.',
    'register_repoint_pause_resume_re_key_and_delete_webhook_59f2b3cf' => 'Registrace koncových bodů webhooků, změna cíle, pozastavení, obnovení, výměna klíčů a odstranění. Nové nebo vyměněné podpisové tajemství se zobrazí pouze jednou.',
    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Registrace, pozastavení, aktivace a odstranění hooků — koncových bodů, které mohou přidávat atributy do tokenů nebo odmítnout přihlášení.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Vytváření, vypínání, obnovení a odstranění streamů auditních záznamů. Vygenerovaný podpisový klíč se zobrazí pouze jednou.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Zaznamenávání auditních událostí vyvolaných uživateli vaší aplikace pro organizace, ve kterých nastaly. Pouze oprávnění potřebná pro backend odesílající události.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Čtení auditních událostí odeslaných vaší aplikací a jejich exportů, ověření řetězce organizace a čtení schémat a pravidel uchovávání těchto událostí.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Spuštění exportu auditních událostí odeslaných vaší aplikací do CSV — stejných událostí, které zpřístupňuje rozsah pro čtení, v jednom souboru.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definování, nahrazování a odstraňování schémat pro validaci auditních událostí a změna doby jejich uchovávání — zkrácení této doby trvale smaže starší události.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Čtení autorizačního schématu a jeho n-tic a provádění kontrol a dotazů na seznamy — „Smí tento uživatel upravit tento dokument?“, „Které dokumenty může vidět?“. Pouze oprávnění potřebná pro backend aplikace k vynucování přístupu.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Zápis a mazání n-tic vztahů — kdo vlastní, upravuje nebo prohlíží které prostředky vaší aplikace. Zápis okamžitě uděluje nebo odebírá přístup v aplikaci.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Nahrazení autorizačního schématu — typů prostředků a způsobu vyhodnocování jednotlivých vztahů. Okamžitě mění odpovědi na všechny kontroly v tomto prostředí.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Čtení zásad ověřování, poskytovatelů sociálního přihlášení a deklarace staršího přihlašování — nikdy tajemství poskytovatele.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Změna pravidel hesel, MFA a SSO, samoobslužné registrace, poskytovatelů sociálního přihlášení a schválení staršího přihlašování.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Čtení režimu Radaru, vestavěných a vlastních pravidel, seznamů povolených a blokovaných položek a přehledu rozhodnutí — proč bylo přihlášení či registrace povoleno, podrobeno dodatečnému ověření nebo zablokováno. Nikdy nezpřístupňuje IP ani jinou adresu z rozhodnutí.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Zápis, změna pořadí a mazání pravidel Radaru, úprava vestavěných pravidel a přidávání či odebírání položek seznamů povolených a blokovaných.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Přepínání Radaru mezi sledováním (pouze záznam) a vynucováním (blokování a dodatečné ověřování) — zapnutí či vypnutí ochrany přihlášení v prostředí.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Zobrazení zveřejnitelných klíčů, které aplikace v prohlížeči předkládají rozhraní Frontend API, a jejich povolených původů.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Vytváření zveřejnitelných klíčů, změna původů, které je mohou předkládat, a odvolávání klíčů.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Zobrazení aplikací, které tomuto prostředí důvěřují jako poskytovateli identity SAML — nikdy jejich certifikátů.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Registrace, změna a odstranění aplikací, do kterých se uživatelé přihlašují pomocí zdejšího účtu.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Čtení motivu a vizuální identity hostovaného přihlašování prostředí a jeho organizací.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Změna motivu a vizuální identity hostovaného přihlašování prostředí a jeho organizací.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Čtení vlastní domény tohoto prostředí a záznamu DNS, který ji ověřuje.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Přidávání, ověřování a odstraňování vlastní domény, na které je toto prostředí dostupné.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Trvalé vymazání osoby (čl. 17 GDPR): její přihlašovací údaje, relace, členství a osobní údaje se smažou a účet se pseudonymizuje. Nelze vrátit zpět.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Vytváření, přejmenování, změna oprávnění a mazání rolí a definování ručních oprávnění, ze kterých se skládají. Přidělování rolí uživatelům spadá pod `roles:write`.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Zobrazení připojení SAML a OIDC, přes která se organizace přihlašují, a e-mailových domén, které na ně uživatele směrují — nikdy certifikátů, tajemství klienta ani podpisových klíčů.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Vytváření, změna, povolování, zakazování a mazání připojení SSO, vyžadování SSO pro organizaci a ověřování jejích e-mailových domén a vynucování SSO pro ně. Mění způsob přihlašování uživatelů.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Zobrazení adresářů (SCIM, Google Workspace, Microsoft Entra), ze kterých se synchronizují uživatelé, jejich skupin a chyb synchronizace — nikdy bearer tokenů ani přihlašovacích údajů poskytovatele.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Připojování, přejmenování, pozastavení, výměna klíčů a mazání zdrojových adresářů a mapování jejich skupin na role. Nový nebo vyměněný SCIM bearer token se zobrazí pouze jednou.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Zobrazení cílových systémů SCIM, do kterých toto prostředí odesílá uživatele, a informace o případných selháních — nikdy jejich přihlašovacích údajů.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Registrace, pozastavení, obnovení a mazání cílů SCIM, do kterých toto prostředí odesílá údaje uživatelů.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Čtení pravidel konfliktů rolí (oddělení povinností) a přezkumů přístupu včetně všech položek, které má někdo potvrdit.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Definování, zapínání, vypínání a odstraňování pravidel konfliktů rolí; zahajování přezkumů přístupu, zaznamenávání rozhodnutí a uzavírání přezkumů — uzavření provede všechna odebrání přístupu.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Zobrazení přihlašovacích údajů pro navazující systémy uložených v trezoru tokenů a aplikací, které k nim mohou získat dočasný přístup — nikdy uložených hodnot.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Ukládání, rotace a odvolávání přihlašovacích údajů pro navazující systémy a udělování či odebírání práva aplikace na dočasný přístup k nim. Nejde o rozsahy vault.manage / vault.lease obsažené ve vlastním tokenu aplikace.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Zobrazení příznaků funkcí a jejich cílení a vyhodnocení každého příznaku pro uživatele v organizaci — to, na co se backend aplikace dotazuje, když nemá token.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Definování, přepínání, změna cílení a mazání příznaků funkcí — které funkce získají kteří uživatelé a organizace.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Zobrazení externích poskytovatelů, ke kterým mohou uživatelé připojit své účty, aplikací s právem dočasného přístupu k těmto tokenům a připojených uživatelů — nikdy tajemství klienta ani tokenů.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Konfigurace, změna a odstranění integrací pipes, udělování nebo odebírání práva aplikace na dočasný přístup k tokenům připojených účtů a odpojování účtů uživatelů.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Zobrazení nedávných odkazů organizace do administračního portálu: co otevírají, kdo je vytvořil, komu byly zaslány a jejich stav — nikdy samotných odkazů.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Vytváření a odvolávání jednorázových odkazů do administračního portálu, které IT správci organizace umožní nastavit SSO, domény či synchronizaci adresářů bez účtu. Nový odkaz se zobrazí pouze jednou.',
