    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Kód lze odcizit výměnou SIM karty nebo neoprávněným přenesením čísla, zachytit v telefonní síti nebo vylákat přesvědčivou falešnou přihlašovací stránkou. Stále je to mnohem lepší než samotné heslo — zapněte tuto metodu lidem, kteří nemohou používat autentizační aplikaci ani přístupový klíč.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Logo načítané z jiného webu informovalo tento web o každém, kdo otevřel vaši přihlašovací stránku. Hostované stránky proto nyní zobrazují pouze obrázky nahrané sem. Nahrajte logo níže v části :part2 nebo ho odeberte, aby toto upozornění zmizelo.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 se může přihlašovat heslem nebo přes toto připojení. Vyžadování jednotného přihlášení odmítne všechny ostatní způsoby přístupu, takže nic dříve vydaného nemůže obejít právě nastaveného poskytovatele. Většina firem, které připojují IdP, toto chce — nejprve si však přečtěte důsledky.',
