    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Jeho členové se mohou znovu přihlašovat a jeho prostředí obnoví ověřování.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Vlastní přihlašovací údaje namísto údajů prostředí pro tohoto poskytovatele.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Klíč vytvořen. Vložte ho do frontendu — je určen ke zveřejnění.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Klíč obnoven — zkopírujte si nyní nový. Starý klíč funguje ještě 24 hodin.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Na přihlašovací stránce nabízí tlačítka Google, GitHub, Apple a dalších poskytovatelů pro lidi, kteří chtějí použít stávající účet místo vytváření dalšího hesla. Poskytovatele nastavíte jednou pro prostředí a bude dostupný všem organizacím. Organizace může použít vlastní přihlašovací údaje nebo poskytovatele vypnout. Zadáte přihlašovací údaje a zbytek se vyplní automaticky. Samotná adresa předaná poskytovatelem nikdy nestačí k přístupu k již existujícímu účtu.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Klíče, kterými se váš kód prokazuje službě Cbox ID, s vlastní kartou pro každý typ. Tajný klíč neboli klíč pro správu umožňuje backendu spravovat organizace, členy, pozvánky, role a aplikace jednoho prostředí. Klíč organizace volá její API s vestavěnou rolí. Veřejný klíč patří do aplikace v prohlížeči a funguje pouze z povolených zdrojů. Tajné klíče a klíče organizace se zobrazují jen jednou. Při vytvoření je zkopírujte a při úniku okamžitě odvolejte.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registruje aplikace, které přijímají toto prostředí jako poskytovatele identity SAML, takže se do nich uživatelé přihlašují svými zdejšími účty. Ke každé přiřaďte její organizaci, aby přístup měli jen členové této organizace. Bez přiřazené organizace je aplikace dostupná všem uživatelům prostředí. Jde o odchozí směr. Pro přihlášení firemním účtem z jiného systému použijte Podnikové SSO v části Ověřování.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Vyberte framework, ve kterém vyvíjíte. Vytvoří se aplikace s přesměrováním na místní vývojový server, blokem konfigurace prostředí ke vložení a kódem pro přihlášení uživatele. Stránka čeká na skutečné přihlášení. Níže jsou kroky přípravy produktu: vzhled značky, organizace, jednotné přihlašování, agent, kolega a produkční provoz. Dokončení se označuje podle skutečného stavu prostředí, nikdy ručně.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar vyhodnocuje každé přihlášení a registraci: pokusy s odcizenými přihlašovacími údaji, rychlost typickou pro boty, nemožné přesuny, nová zařízení, anonymizační sítě a jednorázové adresy i vaše vlastní pravidla a seznamy povolených a blokovaných hodnot. Zaznamenává každé rozhodnutí a po zapnutí vynucování blokuje přístup nebo požaduje druhý faktor. Rozhodnutí si zde prohlédněte před zapnutím vynucování i tehdy, když se někdo nemůže přihlásit.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Přepínače funkcí, na které se aplikace dotazují pro určitou osobu v organizaci. Zapněte funkci vybraným uživatelům, organizacím nebo části všech uživatelů. Každá aplikace přečte stejnou odpověď, z tokenu nebo přes API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software, který v tomto prostředí jedná pomocí klíče pro správu: Claude Code, Cursor, interní bot nebo váš backend. Každý má pouze rozsahy oprávnění, které jste mu přidělili, a tam, kde jste to vyžadovali, čeká na vaše schválení.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Příjemce používá stejný tajný klíč. Z 64znakového hexadecimálního klíče vznikne whsec_ následované kódováním base64 tohoto hexadecimálního řetězce — "whsec_" + base64(secret). Klíč, který už začíná na whsec_, se použije beze změny.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizace, uživatelé a aktivní relace ze všech prostředí této instalace a organizace s největším počtem členů. Tento přehled pouze čte data a nikdy nemění prostředí vybrané v konzoli.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Všichni, kdo se mohou přihlásit do této organizace, a odeslané pozvánky, které zatím nikdo nepřijal. Pozvěte lidi e-mailem; přihlášení si nastaví sami, takže nikdy nemusíte spravovat cizí heslo.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Umožněte lidem přihlásit se účtem, který už mají. Poskytovatele nastavíte jednou pro celé prostředí a bude dostupný ve všech organizacích. Organizace může použít vlastní přihlašovací údaje nebo poskytovatele vypnout.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar vyhodnocuje každé přihlášení a registraci: pokusy s odcizenými přihlašovacími údaji, rychlost typickou pro boty, nemožné přesuny, nová zařízení, anonymizační sítě, jednorázové adresy a vaše vlastní pravidla a seznamy. Zaznamenává i důvod rozhodnutí.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Tento uživatel se už nemůže přihlásit do žádné aplikace v tomto prostředí a jeho stávající relace přestanou fungovat při dalším požadavku. Jeho záznamy zůstanou zachované a kdykoli ho můžete znovu aktivovat.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Vyhodnocuje se postupně: seznam blokovaných, seznam povolených, vlastní pravidla shora dolů (rozhodne první shoda) a poté vestavěná pravidla (rozhodne nejpřísnější z těch, která se uplatní). Pokud se nic neshoduje, přístup je povolen.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Většina integrací by měla používat webhooky: spouštějí se až po události a nemohou ji zdržet. Hook použijte jen tehdy, když váš systém musí zasáhnout během přihlašování nebo vydávání tokenu.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Zde se zobrazují vytvořené klíče a údaj o jejich posledním použití.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Ponechte prázdné, pokud nechcete uzamykání — v tomto nasazení je výchozí uzamykání vypnuté.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Umožněte lidem přihlásit se firemním účtem, který již mají, namísto samostatného hesla zde.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Datový proud protokolu byl uložen. Doručení se zkusí znovu při dalším spuštění.',
    'management_key_created_copy_it_now_it_will_not_be_shown_9ec713ad' => 'Klíč pro správu byl vytvořen — zkopírujte si ho nyní, znovu se nezobrazí.',
    'map_a_group_onto_the_roles_everyone_in_it_should_hold_m_1a407a38' => 'Namapujte skupinu na role, které mají mít všichni její členové. Členství se synchronizuje a role se mu přizpůsobují.',
