    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 zatím nemá žádná oprávnění, takže :part2 :part3 je prázdné. Název role zůstává dostupný pro vyhodnocení. :part4',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Tým spravuje uživatel s rolí v organizaci v části Organizace › Tým, nikoli zde.',
    '_part1_only_d798c565' => 'Pouze :part1',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Zatím zde nic neurčuje :part3. Jakákoli změna níže se stane vlastním pravidlem této organizace.',
    '_part1_part2_only_5ce234b9' => 'Pouze :part1 :part2',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Deklarace :part2 znamená něco jiného: určuje, co směla požadovat :part3 :part4, nikoli co smí dělat tato :part5.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Při registraci aplikace zaškrtněte rozsah :part2 :part3. ID token pak obsahuje stejné názvy rolí v deklaraci :part4, kterou očekávají Kubernetes, Grafana a Vault. Nic dalšího není třeba vytvářet.',
