    'a_conflict_is_written_over_roles_so_there_is_nothing_to_1ee9ecc5' => 'Konflikt se definuje mezi rolemi, ale zatím nejsou žádné k dispozici. Nejprve definujte role.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Stránka na :part1. Ponechte prázdné pro otevření konzole s uvedením :part2 v pozvánce.',
    'a_part1_key_you_can_compose_into_roles_e_g_part2_part3_2714a35b' => 'Klíč :part1, který můžete zahrnout do rolí, například :part2. :part3 :part4',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Oprávnění určuje, co smí :part1 dělat po přihlášení. To, co smí požadovat :part2, určuje rozsah oprávnění nastavený při registraci v části :part3 :part4.',
    'a_user_rule_beats_an_organization_rule_which_beats_the_74a29528' => 'Pravidlo pro uživatele má přednost před pravidlem organizace, to před postupným zaváděním a to před výchozí hodnotou. Vypnutý příznak je vypnutý pro všechny.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Přístupová oprávnění se hromadí: lidé mění týmy, ale ponechávají si stará oprávnění, a nikdo si toho nevšimne, dokud se nezeptá auditor. Revize zachytí aktuální stav a vyžaduje u každého přiřazení potvrdit, zda je stále potřebné.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Přístupové tokeny této aplikace uvádějí :part1 jako příjemce :part2. API by mělo přijmout token pouze tehdy, když je v něm uvedeno jako příjemce.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Přístupové tokeny této aplikace uvádějí jako příjemce vydavatele tohoto prostředí, :part1 :part2. To se změní, když aplikace získá rozsah oprávnění některého z vašich registrovaných API.',
    'acme_dashboard_0b433bd7' => 'Přehled Acme',
