    'already_sent_try_again_in_seconds_seconds_and_check_the_e294712c' => 'Již odesláno. Doba do dalšího pokusu (s): :seconds. Mezitím zkontrolujte složku nevyžádané pošty příjemce.',
    'an_app_registered_here_can_sign_your_people_in_and_read_f35bdb6c' => 'Zde registrovaná aplikace může přihlašovat vaše uživatele a číst jejich role, takže přístup spravujete na jednom místě místo zvlášť pro každý produkt.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Aplikace registruje svůj katalog přes SDK. :part1 :part2 Roli můžete vytvořit hned a přidat do ní oprávnění, až budou jejich definice k dispozici.',
    'an_owner_or_admin_can_add_sms_only_next_to_a_stronger_f_07347449' => 'Vlastník nebo správce může přidat SMS pouze vedle silnějšího faktoru. Pokud má jen SMS, bude vyzván k přidání silnějšího faktoru.',
    'and_part1_more_1468d675' => 'a ještě :part1',
