    'apps_registered_by_the_organizations_in_this_environmen_1fd60d9d' => 'Lze jej udělit aplikacím registrovaným organizacemi v tomto prostředí. Ponechte vypnuté, pokud má být rozsah dostupný pouze vašim vlastním aplikacím.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Aplikace posílají uživatele k registraci pomocí :part1 a žádají přihlášeného uživatele o vytvoření organizace pomocí :part2. Obojí je dostupné pouze při zapnutém nastavení.',
    'apps_that_hold_it_keep_it_as_a_typed_scope_which_no_lon_6498e819' => 'Aplikace si jej ponechají jako ručně zadaný rozsah oprávnění, který již nezpřístupňuje toto API. Tokeny jej pro tohoto příjemce přestanou obsahovat.',
    'ask_a_sign_up_radar_flags_to_prove_it_is_a_person_cloud_5b5f2963' => 'U registrací označených Radarem vyžadovat ověření, že jde o člověka, pomocí Cloudflare Turnstile. Při vypnutí se místo toho ověřuje e-mailová adresa.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Dotaz se provede přesně jako ve vaší aplikaci (:part1), se všemi pravidly dědičnosti definovanými ve schématu.',
