    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Vše, co tento klíč používá, okamžitě přestane fungovat. Tuto akci nelze vrátit zpět.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Vše, kam držitel tento klíč zapojil, okamžitě přestane fungovat. Pokud můžete, nejprve jej upozorněte. Tuto akci nelze vrátit zpět.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Když někdo vytvoří API klíč pro vaši aplikaci, objeví se zde spolu s držitelem a povolenými akcemi.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Když se někdo odhlásí nebo správce ukončí jeho relace, odebere jej či deaktivuje, Cbox ID odešle na tuto adresu podepsaný odhlašovací token přímo mezi servery, aby aplikace mohla ukončit i vlastní relaci.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Cíl, kam Cbox ID přesměruje osoby po odhlášení z této aplikace. URI požadované aplikací musí přesně odpovídat některému z uvedených URI, včetně koncového lomítka. Jinak Cbox ID ponechá osobu na vlastní stránce po odhlášení. Nechte prázdné, pokud aplikace po odhlášení nepřesměrovává.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Kde aplikace zveřejňuje podporované role, aby je zde bylo možné přidělovat.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Jaké způsoby přihlášení kromě hesla nabízí :part1 a jak dlouho přihlášení platí. Jsou stejné pro všechny organizace v prostředí.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Kdo patří do této organizace a co smí dělat. Osoba, která zde ještě nemá účet, dostane pozvánku e-mailem.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Kdo získá příznak, pokud jej žádné pravidlo neurčuje. Ponechte vypnuté, chcete-li funkci nejprve zpřístupnit konkrétním organizacím nebo procentu uživatelů.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'Komu role patří, nebo zaškrtněte pole výše a definujte ji pro každou organizaci.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Čí role a členství přezkum zachycuje.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'Komu pravidlo patří, nebo zaškrtněte pole výše a použijte je pro každou organizaci.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Bez rolí dostane každý, kdo se může přihlásit, přístup určený aplikací běžnému uživateli. Role umožňuje jednou určit, kdo jsou editoři a kdo podpora, a všechny připojené aplikace toto přiřazení respektují.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Projděte seznam: potvrďte potřebná práva a nepotřebná odeberte.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Přidejte záznam výše nebo z backendu aplikace v dávkách až po 100.',
    'writes_531995e8' => 'zápis',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Jste jediným vlastníkem. Nejprve převeďte vlastnictví na jinou osobu nebo organizaci smažte.',
    'you_can_also_part1_part2_part3_53f32513' => 'Další možnost: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'Nastavení můžete kdykoli vrátit na „Upřednostnit SSO“ nebo „Obě možnosti dostupné“. Ukončené relace zůstanou ukončené.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Přístup ztratíte okamžitě. Jako vlastník můžete odejít až poté, co vlastnictví převezme někdo jiný. Nejprve je převeďte nebo organizaci smažte v nastavení.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Okamžitě ztratíte přístup k této organizaci a jejím aplikacím. Správce vás může znovu pozvat.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Vlastní přístupový model aplikace: typy prostředků, vztahy každého typu a jejich dědičnost. Aplikace zapisuje n-tice určující, kdo má vztah k čemu, a při každém požadavku ověřuje přístup.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Vaše zásady ověřování nadále platí: síla hesla, kontrola úniků, potvrzení e-mailu, omezení požadavků a kontroly botů.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Vaše vlastní API. U každého rozsahu rozhodujete, zda o něj smějí žádat aplikace registrované organizacemi.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Na přihlašovací stránku přibude odkaz „Vytvořit účet“ a aplikace mohou uživatele posílat přímo k registraci pomocí :part1.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Nastavení můžete kdykoli vrátit na „Upřednostnit SSO“ nebo „Obě možnosti dostupné“. Ukončené relace zůstanou ukončené.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Role a oprávnění v tokenu jsou snímkem stavu v daném okamžiku. Před každou chráněnou akcí získejte aktuální rozhodnutí o přístupu od Cbox ID a v aplikaci ověřte přístup ke konkrétnímu prostředku. Samotný obsah tokenu nezohledňuje pozdější odebrání přístupu:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Vaše metody přihlašování a aktivní relace. Přístupový klíč je nejbezpečnější a nejrychlejší možnost: zařízení ho odemkne otiskem prstu nebo obličejem a nezůstává žádné heslo, které by šlo vylákat phishingem.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Každá akce se přijme tak, jak ji aplikace odešle. Přidejte k akci schéma, aby se její události při přijetí ověřovaly. Konzistence protokolu se zajišťuje při zápisu události, ne až při jejím čtení.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Každý klíč API uložený v konfiguraci aplikace nebo souboru prostředí je klíč, který nemůžete centrálně obměnit ani rychle odebrat. Zde je uložen zašifrovaně, přístup k němu se uděluje jednotlivým aplikacím a lze ho odvolat jedním kliknutím.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Tlačítko se přestane zobrazovat a přihlašovací údaje se smažou. Lidem, kteří se přes poskytovatele přihlásili, zůstanou účty a nadále mohou používat heslo. Pokud chcete přihlašovací údaje zachovat, poskytovatele místo smazání vypněte.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Opačný směr: Cbox ID předává vaše lidi do dalších produktů SaaS, které firma používá, přes jejich koncové body SCIM. Jedno místo pro udělování a odebírání přístupu místo samostatné administrace každého dodavatele.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Vytvoří organizaci, jejího vlastníka, první produkt a produkční prostředí tohoto produktu. Vlastník dostane e-mailem odkaz pro nastavení vlastního hesla — nevybíráte ho za něj.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Dnes tu někdo ručně přidává a odebírá lidi. Připojte adresář, který už vaše firma spravuje, a obě činnosti se budou provádět automaticky — včetně odebírání, na které se nejčastěji zapomíná.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Všechny tokeny, které vydal, se nyní odvolají a pro nová přihlášení ho nelze použít. Aplikace, která tokeny ověřuje sama, je přestane přijímat při vypršení jejich platnosti, nejpozději na konci samotné relace.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Při migraci z jiného systému může aplikace ve svém manifestu vedle rolí uvést, kde je její původní přihlašování. Zde se zobrazí ke schválení, než začne cokoli dělat.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Vytvořte pravidlo, které podle vašich znalostí uživatelů přístup povolí, vyžádá další ověření nebo ho zablokuje. Vyžadujte další ověření při přihlášení ze zemí, ve kterých nepůsobíte, nebo vyjměte kancelářskou síť z pravidel četnosti.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Ověření vlastní domény, například acme.com, umožní Cbox ID rozpoznat vaše lidi podle e-mailové adresy a poslat je přímo k vašemu poskytovateli, takže nikdo nemusí vybírat správné přihlašovací tlačítko.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Poskytovatel identity, který importuje metadata poskytovatele služby, použije tuto URL místo samostatného zadávání ID entity a URL ACS. Funguje ještě před vyplněním konfigurace na straně poskytovatele identity.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Tuto akci nelze vrátit zpět. Přihlašovací údaje, členství a osobní údaje se smažou a účet se pseudonymizuje. Pokud jde o jediného vlastníka organizace, nejprve vlastnictví převeďte.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Jednáte jako tato osoba, v její relaci a s jejími oprávněními. Přístup je omezen na 30 minut a pouze na čtení tam, kde to konzole dokáže vynutit. Každý požadavek se zaznamená pod vaším jménem.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Pozastavení je jediná změna prováděná na této stránce a lze ho zrušit. Výběr a otevření prostředí mění pouze zobrazení konzole; v žádném prostředí nic nemění.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Nyní se lidé přihlašují pomocí přihlašovacích údajů uložených zde. Připojte svého poskytovatele a budou používat stávající firemní účet; jakmile ho u poskytovatele zakážete, ztratí přístup i zde.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Nevydává se nový tajný klíč. Od dalšího pokusu, včetně opakování, budou doručení obsahovat hlavičky druhého schématu. Příjemce, který nebyl aktualizován, je všechna odmítne.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Pošlete tento jednorázový odkaz správci jejich poskytovatele identity, pokud ho nedostal e-mailem. Do vypršení platnosti funguje bez účtu. Zkopírujte ho nyní — zobrazuje se pouze jednou.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Software v tomto prostředí, který čeká na povolení člověka. Agent, jehož klíč vyžaduje schválení, se zastaví a požádá člověka, který klíč vytvořil. Odpovězte zde nebo na telefonu.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Organizace sdružuje uživatele, metody přihlášení a role. Vytvořte ji výše nebo inicializujte prostředí první organizací a správcem na stránce Prostředí.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Přidejte tuto osobu do některé z níže uvedených organizací a udělte jí v ní přístup. Pokud aplikace nemají vlastní oddělení organizací, přidělte jí roli správy a podpory platnou v celém prostředí.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Role správy a podpory je role přidělená vlastním pracovníkům v celém prostředí. Platí v každé organizaci a správci žádné organizace ji nemohou zobrazit ani změnit.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Žádosti se zde automaticky objeví, když aplikace nebo agent potřebuje vaše schválení, aby mohl jednat vaším jménem. Do té doby není potřeba nic dělat. Pokud se objeví žádost, kterou jste nezahájili, zamítněte ji.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS jsou nejslabší druhý faktor: kdo převezme vaše telefonní číslo, dostane vaše kódy. Upřednostněte ověřovací aplikaci nebo přístupový klíč a SMS použijte, jen pokud tyto možnosti nemůžete využít.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Výchozí vizuální identita prostředí: vzhled hostované přihlašovací stránky, logo a favicon i název a odesílatel zobrazovaní uživatelům. Každá organizace nastavení zdědí, pokud si neurčí vlastní.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Podrobnosti organizace v cílovém prostředí: členové, SSO, domény, nároky a nedávná aktivita. Z této stránky lze změnit pouze stav organizace.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Všechny organizace této instalace. Otevřete některou a prohlédněte si její produkty a prostředí. Pozastavení odhlásí její členy a zastaví ověřování identity ve všech prostředích, která vlastní.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Tyto události posílá aplikace: jedno volání na dávku a každá událost uvádí organizaci, ve které nastala. Jak přicházejí, zobrazují se zde i správcům dané organizace.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Je dostupný na všech přihlašovacích stránkách prostředí. Vyberte organizaci a nastavte jí vlastního poskytovatele, který na její stránce nahradí poskytovatele prostředí.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code otevře prohlížeč pro přihlášení zde a zeptá se, co chcete povolit. Nemusíte uchovávat žádný klíč. Stejně s touto URL funguje každý klient MCP, který se přihlašuje přes OAuth.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Jedna organizace této instalace: její tým, projekty a všechna prostředí těchto projektů. Pozastavení odhlásí členy a zastaví ověřování identity ve všech těchto prostředích.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Pro celé prostředí: do této aplikace se může přihlásit kdokoli s účtem v tomto prostředí, z libovolné organizace. Pokud takto široký přístup nechcete, uveďte organizaci.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Přihlašování přes Entra ID, Okta nebo Google Workspace je dostupné v tarifu Enterprise. Pro aktivaci v této organizaci kontaktujte tým, který se stará o váš účet.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Kde jste přihlášeni, co může jednat vaším jménem a co se dělo s vaším účtem. Pokud uvidíte něco, co nepoznáváte, ukončete danou relaci a změňte heslo.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Kolik lidí se přihlásilo a jak často aplikace volaly API za posledních 30 dní. Údaje slouží k přehledu o zátěži a hledání anomálií; nejde o fakturu.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Tento uživatel vlastní nebo spravuje organizaci, a proto se za něj nelze vydávat. Vstup do takového účtu by mohl dát dotyčnému trvalou kontrolu nad organizací.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Klíče API, kterými se vaše aplikace a agenti prokazují jiným službám. Každá hodnota je v úložišti zašifrovaná, předává se jen aplikacím, kterým udělíte přístup, a po uložení už se nezobrazí.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplikace žádající o jednání jménem některého z vašich uživatelů. Každý uživatel schvaluje vlastní žádosti. Zde žádost zamítněte, jen pokud vypadá jako zneužití; zamítnutí se zapíše do auditního protokolu.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Jak často načítat data a která vlastní pole personálního systému kopírovat ke každé osobě, například nákladové středisko nebo lokalitu. Změna polí způsobí, že příští běh bude úplný.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Odkazy předané správci IT této organizace, které stále poskytují přístup. Odvolání odkazu ho okamžitě zneplatní; to, co se přes něj už nastavilo, zůstane zachované.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Žádosti agentů o jednání jménem uživatele se zde zobrazují, jak přicházejí. Každý uživatel schvaluje své vlastní. Tato stránka slouží k zamítnutí žádostí, které vypadají jako zneužití.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Když platí VŠECHNY podmínky, Radar provede akci tohoto pravidla a další pravidla už nevyhodnocuje. Pravidla se vyhodnocují po seznamech povolených a blokovaných a před vestavěnými pravidly.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Auditní události, které aplikace posílá o všech obsluhovaných organizacích, od nejnovějších. Události každé organizace tvoří vlastní řetězec hashů.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Vše, co má organizace nastavené, i to, co zbývá udělat. Kontrolní seznam sleduje skutečný stav: krok se sám označí jako hotový ve chvíli, kdy je opravdu dokončený.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Jako správce přidejte také ověřovací aplikaci nebo přístupový klíč. Převzetím telefonního čísla lze získat i vaše SMS, proto nemohou být vaším jediným druhým faktorem.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Smazání této organizace odstraní všechny její projekty a prostředí. Kvůli ochraně aktivních poskytovatelů identity tuto akci nelze provést samoobslužně. Pro pokračování kontaktujte podporu.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Okamžitě ztratí přístup ke všem stránkám platformy v této instalaci a stávající relace přestanou fungovat při dalším požadavku. Zde je můžete znovu aktivovat.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Ověřené domény směrují lidi k vašemu vlastnímu poskytovateli identity, což je součást tarifu Enterprise. Pro aktivaci v této organizaci kontaktujte tým, který se stará o váš účet.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Oprávnění určuje jednu věc, kterou role smí dělat, například vytvářet faktury nebo číst přehledy. Vlastní oprávnění zde vytvoříte bez kódu a pak je seskupíte do rolí. Aplikace mohou svá oprávnění registrovat automaticky, aby seznam odpovídal tomu, co skutečně vynucují. Oprávnění, která vytvoříte, patří vám. Oprávnění sdílená prostředím můžete používat, ale ne měnit.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Pravidla hesel, uzamčení, povinného druhého faktoru a jednotného přihlašování platná při každém přihlášení. Pro celé prostředí se nastavuje také dostupnost přístupových klíčů a přihlašovacích odkazů a délka relace. Prostředí určuje základ, který přebírají všechny organizace. Organizace může pravidla hesel a druhého faktoru zpřísnit, nikdy však zmírnit.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Akce, u kterých agenti v tomto prostředí čekají na souhlas člověka. Agent, jehož klíč vyžaduje schválení akce, se zastaví a požádá člověka, který klíč vytvořil. Ten může odpovědět na telefonu nebo zde. Kdokoli, kdo spravuje prostředí, může podezřelý požadavek zamítnout. Níže jsou žádosti aplikací o jednání jménem uživatelů, které každý uživatel schvaluje sám.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Relace a tokeny této osoby budou odvolány. Její přístupové klíče, druhé faktory, členství, přiřazení rolí, API tokeny, tajné údaje v trezoru, zařízení a všechny uložené kopie jejích údajů budou odstraněny. Z účtu zůstane jen pseudonymizovaný, deaktivovaný záznam. Aplikace, které odtud synchronizují osoby, dostanou pokyn k jejímu odstranění. Auditní protokol zachová neprůhledný identifikátor, nikoli jméno ani adresu.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Vše, co jste schválili, včetně zařízení nebo nástrojů příkazového řádku, ze kterých jste se přihlásili.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Údaje, které vaše systémy potřebují uchovávat u této organizace. Řádky bez klíče se vynechají.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Vyhodnocují se po vašich pravidlech. Každé spuštěné pravidlo se zaznamená; rozhoduje nejpřísnější.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Doručování se obnoví. Záznamy vytvořené během pozastavení stále čekají a odešlou se v další dávce.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Doručování se okamžitě zastaví a uložený přihlašovací údaj se zničí. Auditní záznamy zůstanou beze změny.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Všechna propojení mezi Cbox ID a dalšími systémy na jednom místě: jednotné přihlašování, přihlášení sociálním účtem, synchronizace adresářů a HR systémy, odchozí provisioning, SAML aplikace, webhooky, hooky, přenosy protokolů a datové kanály. Z katalogu spustíte nastavení libovolného typu — každá karta otevře příslušnou stránku. Seznam připojení ukazuje všechna existující propojení a jejich stav, nejprve ta s chybou.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Všechny způsoby přihlášení — heslo, přístupové klíče, přihlašovací odkaz, sociální účet, podnikové SSO a druhý faktor — včetně toho, zda jsou zapnuté a kde se nastavují. Většinu určuje prostředí, SSO připojení patří jednotlivým organizacím. Pokud je metoda vypnutá nebo omezená nastavením instalace, stránka to uvádí i s názvem příslušného nastavení.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Agent je jakýkoli software, který v tomto prostředí jedná s klíčem pro správu: AI asistent jako Claude Code nebo Cursor, interní bot nebo váš backend. Každému dejte vlastní klíč pouze s potřebnými rozsahy. Určete, které akce mají čekat na schválení, a klíč odvolejte, jakmile agent skončí nebo se něco bude zdát podezřelé.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API je vaše služba, která přijímá přístupové tokeny, například https://api.example.com. Zaregistrujte ji s rozsahy, které rozpoznává, abyste je mohli přidělovat. Určujete, o které rozsahy mohou žádat aplikace registrované organizacemi v tomto prostředí. Token pro API nese jeho adresu jako cílového příjemce, kterého vaše služba ověřuje.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Jak auditní stopa opouští Cbox ID: plánovaný export odesílá nové záznamy do SIEM nebo archivu každých pět minut. Denní úloha uchovávání vytváří kontrolní bod bez mazání dat. Zde získáte auditní historii jedné osoby pro žádost o přístup podle GDPR nebo v konzoli prostředí ověříte, zda exporty běží.',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Zadejte přesně uvedený text. Tlačítko „:part1“ zůstane neaktivní, dokud se text neshoduje.',
    'my_part1_app_40bca4ad' => 'Moje aplikace :part1',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Jeden dlouhodobě běžící proces, php artisan queue:autoscale, spouští a zastavuje pracovní procesy, které zpracovávají úlohy ve frontě.',
    'this_will_allow_part1_to_6ac64554' => 'Aplikace :part1 bude moci:',
