    'every_queue_this_install_sends_background_work_through_562c4113' => 'Všechny fronty úloh na pozadí této instalace a doba čekání nejstarší úlohy v každé z nich',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Všechny čítače využití pro toto období a původní klíče příslušných metrik',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Vyhledejte organizaci nebo uživatele ve všech prostředích, nejen v prostředí právě vybraném v konzoli.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Žádná přihlášená doména neodpovídá hledání. Zkuste část domény bez @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Tomuto názvu neodpovídá žádné připojení. Zkuste jiný hledaný výraz.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Tomuto názvu neodpovídá žádný adresář. Zkuste jiný hledaný výraz.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Hledání neodpovídá žádná URL koncového bodu. Zkuste jiný výraz.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Těmto filtrům neodpovídá žádný záznam. Zkuste obecnější výraz nebo odeberte filtr.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Tomuto názvu neodpovídá žádný proud protokolů. Zkuste jiné hledání.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Tomuto názvu neodpovídá žádné odchozí připojení. Zkuste jiné hledání.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Všechny prvky značky, které uživatelé vidí, na jedné stránce: logo, favicon, barvy, písmo a zaoblení hostované přihlašovací stránky s živým náhledem, dále název produktu, odesílatel e-mailů a uvítací e-mail. Nastavte je jednou pro celé prostředí a všechny organizace je převezmou, nebo dejte jedné organizaci vlastní vzhled na kartě Vzhled značky.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Každý projekt v organizaci má vlastní tarif a limit prostředí. Zde jsou uvedeny spolu s využitím za tento měsíc: organizace, účtovaná připojení jednotného přihlašování a přihlášení. Cena zohledňuje měsíčně aktivní uživatele a podniková připojení, například SSO a SCIM. U testovacích prostředí se za připojení neplatí.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Všechny API klíče vytvořené lidmi v této organizaci pro její aplikace: držitel, aplikace, oprávnění a poslední použití. Klíč smí jen to, co jeho držitel, a po jeho odchodu z organizace přestane fungovat. Odvolejte klíče, které unikly nebo se už nepoužívají. Každý si vlastní klíče vytváří v části Můj účet.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Při migraci z jiného systému může aplikace požádat o ověření e-mailu a hesla osoby, která ještě není v Cbox ID, na starém přihlašovacím koncovém bodu. Před schválením jej otestujte. Přijatá osoba se vytvoří zde a do starého systému se už neodesílá. Pokud však tento koncový bod nefunguje, dosud nepřevedení uživatelé se nemohou přihlásit.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Auditní události, které vaše aplikace odesílá pro každou obsluhovanou organizaci: kdo ve vašem produktu co udělal a kdy. Uchovávají se odděleně pro každou organizaci v řetězci hashů a zobrazují jejím správcům. Použijte je, když organizace požádá o auditní protokol svého účtu. Definujte schémata, aby události zůstaly konzistentní.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Žádné budoucí dočasné oprávnění neumožní otevřít tento tajný údaj. Odvolání je okamžité a trvalé.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Žádní aktivní agenti. Odvolané klíče a klíče s prošlou platností zůstávají v seznamu pro evidenci.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Bez oprávnění — pouze identifikuje držitele',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Dokud tuto možnost nezapnete, nic se pro nikoho nezmění. Nejprve vyzkoušejte přihlášení.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Ukládá se pouze hash. Pokud klíč ztratíte, odvolejte jej a vytvořte nový.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Pouze zde uvedené aplikace mohou získat dočasný přístup k tomuto tajnému údaji. Všechny ostatní požadavky se zamítnou.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Relace na všech ostatních zařízeních přestanou fungovat při příštím požadavku. Na tomto zařízení zůstanete přihlášeni.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Tato organizace zatím nemá členy. Nikdo se do ní nemůže přihlásit, dokud nebude pozván nebo přidán prostřednictvím provisioningu.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Heslo se zde nenastavuje. Uživatel obdrží e-mailem přihlašovací odkaz a zvolí si způsob přihlašování.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Každý krok se vyhodnocuje podle aktuálního stavu, takže průvodce vždy ukazuje skutečnou situaci této organizace.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Zkopírujte klíč nyní a předejte jej agentovi. Uchovává se pouze hash, takže klíč se zobrazuje jen jednou.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'E-mailové domény této organizace, každá ověřená pomocí DNS TXT záznamu. Po ověření domény můžete zapnout vynucené směrování na SSO: všichni s adresou v této doméně použijí podnikové SSO místo hesla. Než se spolehnete na jednotné přihlašování, ověřte všechny domény používané vašimi lidmi.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Vlastní přístupový model aplikace: typy prostředků, například dokumenty a složky, vztahy jako vlastník, editor a čtenář a jejich dědění. Čtenáři složky mohou například číst všechny dokumenty v ní. Aplikace zapisuje vztahy osob k prostředkům a při každém požadavku se ptá, zda uživatel smí upravit daný dokument. Odpověď určuje schéma.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Toto prostředí vedle REST API poskytuje MCP server, standardní způsob, jak AI asistenti volají nástroje. Vložte adresu a klíč pro správu do Claude Code, Cursor nebo jiného MCP klienta. Agent smí přesně to, co povolují rozsahy klíče, se stejnými kontrolami a auditním protokolem jako v konzoli.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Klíč umožňuje vašim skriptům a integracím volat API aplikace vaším jménem bez přihlášení. Smí jen to, co v dané aplikaci smíte vy: při omezení vašeho přístupu jej ztratí i klíč. Klíč se zobrazuje jen jednou. Při vytvoření jej zkopírujte a okamžitě odvolejte, pokud unikne nebo jej přestanete používat.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Provisioning se zastaví a mapování skupin se odstraní. Vytvoření uživatelé zůstanou.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Provisioning se okamžitě zastaví a všechna mapování skupin se odstraní. Tuto akci nelze vrátit zpět.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Provisioning do cílové aplikace se okamžitě zastaví. Tuto akci nelze vrátit zpět.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Provisioning do cílové aplikace se okamžitě zastaví. Již vytvoření uživatelé v ní zůstanou.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Telefonní číslo bylo odebráno. Ostatní ověřovací faktory a kódy pro obnovení uživatele zůstávají beze změny.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Již připojení uživatelé si ponechají rozsahy, které schválili, dokud se znovu nepřipojí.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Původy byly aktualizovány. Změna se projeví při příštím požadavku.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Tuto hodnotu mohou používat jiné systémy. Její změna změní adresy URL, které mají uložené.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Uživatelé závislí na tomto poskytovateli přijdou o tento způsob přihlášení. Tuto akci nelze vrátit zpět.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Projekt byl pozastaven. Jeho prostředí zůstávají aktivní, ale nová nelze přidávat, dokud projekt znovu neaktivujete.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Definice role byla aktivována. Stávající držitelé nyní používají tato oprávnění.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Pravidlo bylo aktivováno. Udělení přístupu, která by jej porušila, jsou od nynějška blokována.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Schéma bylo uloženo. Události této akce se od nynějška kontrolují podle něj.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Schéma bylo uloženo. Od nynějška určuje výsledek každé kontroly.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Odmítat události, jejichž akce nemá schéma. Zapněte, až bude mít schéma každá akce odesílaná vaší aplikací.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Objekty se zapisují do prefix/yyyy/mm/dd/hh/batch.ndjson.gz, jedna událost na řádek.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Pouze pro úložiště kompatibilní s S3, například MinIO nebo Cloudflare R2. Prázdná hodnota použije koncový bod AWS pro danou oblast.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Zaregistrujte tuto hodnotu u poskytovatele jako povolené URI přesměrování, přesně v uvedené podobě.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooky, oznámení o odhlášení připojeným aplikacím, aktualizace rolí získávané z těchto aplikací a e-maily ve frontě zpracovávají procesy fronty na pozadí, bez čekání uživatele. Pokud žádný proces neběží, nic se neodešle, ačkoli zbytek konzole vypadá v pořádku. Na této stránce problém uvidíte.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Kontrola, při které projdete, kdo má jakou roli, a potvrdíte, zda ji ještě potřebuje. Přístupy se nenápadně hromadí: lidé mění týmy a ponechávají si stará oprávnění. Kontrola umožňuje tyto přístupy odebrat. Odebrání se provede při uzavření kontroly a celý průběh se zaznamená pro auditora.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Pokud aplikace později uvede jinou URL, toto schválení se zruší a budete požádáni znovu. Změna místa, kam se posílají hesla, vyžaduje nové schválení. Delegované přihlášení slouží k přechodu: až ve starém systému zbude jen málo lidí, vypněte je a pošlete této skupině obnovení hesla.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Umožňuje přihlášení stávajícím firemním účtem, například Microsoft Entra ID, Okta nebo Google Workspace, místo samostatného hesla zde. Jednou připojíte poskytovatele identity a ověříte své e-mailové domény. Všichni uživatelé těchto domén pak budou při přihlášení směrováni k poskytovateli.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Všichni lidé s identitou v tomto prostředí bez ohledu na organizace, do kterých patří. Otevřete osobu pro obnovení hesla či druhého faktoru, ukončení relací, deaktivaci účtu, změnu organizací a rolí nebo trvalý výmaz na základě žádosti o uplatnění práva na výmaz.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Vložte XML metadat poskytovatele nebo jejich URL a pole níže se vyplní automaticky.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Vložte tuto hodnotu u svého poskytovatele identity spolu s bearer tokenem připojovaného adresáře.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Nastavte tyto adresy v klientovi OIDC. Automatické zjišťování zpřístupní všechny koncové body.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Zaregistrujte aplikaci, která používá toto prostředí jako poskytovatele identity SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Zaregistrujte aplikaci, aby se do ní uživatelé mohli přihlašovat pomocí účtů, které již mají v tomto prostředí.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Token získají pouze zde uvedené aplikace. Všechny ostatní požadavky se zamítnou.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Tato organizace nemá nastavená oprávnění k funkcím. Používá výchozí nastavení nasazení.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Organizace v cílovém prostředí zobrazené jako strom správy.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Vlastněno tímto prostředím, nikoli organizací',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Provozovatelé platformy spravují prostředí v celé instalaci.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Využití celé platformy napříč všemi prostředími, nejen prostředím právě vybraným v konzoli.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Způsob přihlašování vlastníků a provozovatelů organizací do Cbox ID se nastavuje v konzoli prostředí platformy.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Tyto rozšiřující body se spouštějí během operace, ne po ní, a jejich odpověď mění výsledek: váš endpoint může doplnit informace do tokenu nebo přihlášení rovnou odmítnout. Zasahují přímo do průběhu operace — pomalý nebo nefunkční endpoint pocítí člověk, který se pokouší přihlásit.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Poskytovatel identity zde sám vytváří, aktualizuje a deaktivuje osoby pomocí standardu SCIM. Nástup nebo odchod zaznamenaný v personálním systému se během sekund projeví v aplikacích, bez požadavků na podporu a zapomenutých účtů — což je zvlášť důležité při odchodu.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Počty organizací, uživatelů, připojení jednotného přihlášení, aplikací a synchronizací uživatelů v tomto prostředí, každý s odkazem na příslušnou stránku. Zkratky níže zahajují nejčastější akce: vytvoření organizace, uživatele, připojení jednotného přihlášení nebo aplikace.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Role je označení pracovní odpovědnosti, kterému vaše aplikace rozumějí, například „Editor“ nebo „Pracovník podpory“. Zde určujete, kdo má jakou roli; každá aplikace sama určuje její oprávnění. Role osobu provázejí ve všech připojených aplikacích, takže přístup udělujete i odebíráte na jednom místě.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Při zápisu kopíruje každý záznam auditního protokolu do nástrojů bezpečnostního týmu, například do systému SIEM. Nastavte cíl, aby šetření začínalo v nástrojích, které tým již používá, bez žádosti o export. Doručení proběhne alespoň jednou, takže se mohou objevit duplicity.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Organizace se zde objeví, jakmile se někdo zaregistruje. Můžete ji také vytvořit pomocí volby Nová organizace výše.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Přidejte doménu e-mailových adres členů této organizace, zveřejněte záznam TXT a ověřte doménu.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Ověřte vlastnictví e-mailové domény a automaticky směrujte svůj tým na SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Ověřte, že organizace vlastní doménu, a směrujte všechny její uživatele na přihlašování organizace.',
