    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'Ukládá se zašifrovaný a znovu se nezobrazí. Ponechte prázdné pro zachování stávající hodnoty.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Tajný údaj byl vyměněn a předchozí přestal fungovat. Zkopírujte nový nyní — znovu se nezobrazí.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'Odvolání je okamžité a trvalé. Žádné budoucí dočasné oprávnění neumožní otevřít tento tajný údaj.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Schémata metadat jsou podmnožinou JSON Schema: objekt, jehož vlastnosti jsou řetězce, čísla, celá čísla, logické hodnoty nebo null, s výčty a omezeními délky, rozsahu, vzoru a formátu. Uložením změny vznikne nová verze; již zaznamenané události si ponechají verzi, podle které byly ověřeny.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Každé propojení umožňuje lidem připojit vlastní účet u služby jako GitHub, Google nebo Slack. Tokeny jsou zde uloženy šifrovaně a průběžně obnovovány. Oprávněné aplikace si při každém volání služby jménem dané osoby vyžádají platný token a samy jej neukládají.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Role pro správu a podporu se uděluje vlastním pracovníkům, například podpoře nebo provoznímu týmu, pro celé prostředí. Platí ve všech organizacích a správci organizací ji nemohou zobrazit, udělit ani odebrat. Vlastní role aplikace udělená tímto způsobem platí pouze v dané aplikaci.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Prostředí je zcela izolovaná služba identity s vlastními uživateli, klíči, přihlášením a vydavatelem. Zde jsou uvedena všechna prostředí této instalace i organizace, kterým patří. Vytvořte prostředí, přepněte na něj konzoli a přidejte první organizaci a správce.',
    'a_chain_is_one_organization_s_send_organization_id_f35ed1e5' => 'Řetězec patří jedné organizaci: odešlete organization_id.',
    'a_support_session_lasts_at_most_max_minutes_069774e6' => 'Maximální délka relace podpory (min): :max.',
