    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Telefon s nainstalovanou ověřovací aplikací umožňuje odpovídat na žádosti o schválení a upozorňuje, když se někdo přihlásí k vašemu účtu. Jednou jej zaregistrujte naskenováním kódu. Pokud telefon ztratíte, ihned jej zde odeberte, aby již nemohl nic schvalovat.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Organizace je zázemí jedné registrované společnosti v této instalaci a obsahuje její projekty, prostředí a tým. Otevřete ji a prohlédněte si produkty a prostředí, nebo ji pozastavte: tím odhlásíte členy a zastavíte přihlašování ve všech jejích prostředích.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Když aplikace nebo AI agent potřebuje váš souhlas k jednání vaším jménem, nemůže se vždy zeptat na obrazovce před vámi — proto žádá zde. Schvalujte jen žádosti, které jste sami zahájili, a ověřte, že zobrazený kód odpovídá kódu na zařízení, které žádost odeslalo.',
