    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Každá organizace je společnost nebo tým používající váš produkt, s vlastními členy, rolemi, doménami a jednotným přihlášením. Vytvořte jednu pro každou registrovanou společnost. Otevřete ji pro správu členů, pozvánek a ověřených domén nebo pro její pozastavení.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID odešle podepsanou zprávu na váš endpoint poté, co se něco stane, například přibude člen nebo se změní role. Vaše systémy tak mohou reagovat bez pravidelného dotazování. Neúspěšné doručení se opakuje. Událost již proběhla: endpoint je informován, ale nerozhoduje o výsledku.',
