    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Všichni správci této organizace, jejich vestavěné role — Vlastník, Správce, Vývojář, Člen nebo Prohlížející — a prostředí, ke kterým mají přístup. Zvěte osoby e-mailem a každé zpřístupněte jen prostředí potřebná k její práci.',
