    'everyone_in_this_organization_is_refused_at_every_door_40e035a5' => 'Všem osobám v této organizaci bude okamžitě odepřen přístup všemi cestami a organizace zmizí ze všech seznamů. Z konzole to nelze vrátit zpět.',
    'everything_on_this_page_is_also_a_rest_endpoint_an_mcp_28d51f03' => 'Vše na této stránce je dostupné i jako REST endpoint, nástroj MCP a příkaz CLI, se stejnými pravidly a auditní stopou.',
    'give_it_a_name_you_will_recognise_later_like_3cdadec6' => 'Zvolte název, který později poznáte, například zařízení nebo správce hesel, ve kterém je uložen. Název lze kdykoli změnit.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Udělte roli lidem, kteří zajišťují podporu nebo provoz aplikací. Vlastní role aplikace se přenáší jen v jejích tokenech; role pro všechny aplikace v tokenech každé z nich.',
    'groups_appear_here_after_the_first_sync_that_includes_t_d8006c0f' => 'Skupiny se zde zobrazí po první synchronizaci, která je zahrnuje. Pokud poskytovatel odesílané skupiny filtruje, seznam odpovídá tomuto filtru.',
