    'the_address_belongs_to_a_hosting_provider_or_data_centr_213f7032' => 'Adresa patří poskytovateli hostingu nebo datovému centru, odkud se lidé přihlašují zřídka. Vyžaduje službu informací o IP adresách, která tuto vlastnost uvádí.',
