    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Do aplikace se mohou přihlásit pouze aktivní členové vybrané organizace. Všichni ostatní jsou odmítnuti a odmítnutí se zaznamená do auditního protokolu.',
    'passkeys_are_turned_off_here_so_you_cannot_a_9b3b4401' => 'Přístupové klíče jsou zde vypnuté, takže nelze přidat nový ani se jím přihlásit. Stávající klíče jsou uvedeny níže a lze je odebrat.',
    'people_who_sign_in_through_this_provider_stop_being_abl_a0fd1fd9' => 'Osoby přihlašující se přes tohoto poskytovatele tuto možnost ztratí. Kdo zde má heslo, může se přihlásit dál, pokud není vyžadováno jednotné přihlášení.',
