    'this_provider_s_discovery_document_publishes_no_signing_07a38178' => 'Dokument pro zjišťování konfigurace tohoto poskytovatele neuvádí podpisové klíče (jwks_uri). Vložte jeho podpisový klíč pro ID tokeny (veřejný klíč PEM).',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Před zapnutím povinného směrování na SSO ověřte doménu. Do té doby organizace neprokázala, že jí tyto adresy patří.',
