    'you_re_signed_in_you_don_t_belong_to_an_orga_67d0efb9' => 'Jste přihlášeni. Zatím zde nepatříte do žádné organizace — váš účet a nastavení zabezpečení jsou pouze vaše.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Potřebujete přihlašovací údaje z vlastního účtu u poskytovatele, obvykle ID a tajný údaj klienta. Apple místo tajného údaje vydává podpisový klíč.',
    'you_stop_being_able_to_sign_in_with_it_if_it_66b928b9' => 'Touto metodou se již nepřihlásíte. Pokud je jediná, změna bude odmítnuta. Nejprve nastavte heslo nebo přidejte přístupový klíč.',
