    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Správcovský klíč funguje pouze ve svém prostředí. Exportujte předlohu této aplikace (GET /apps/{id}/blueprint) a zaregistrujte ji klíčem druhého prostředí (POST /apps s `blueprint`).',
    'add_the_domain_and_publish_the_txt_record_it_shows_or_s_ddb14174' => 'Přidejte doménu a zveřejněte zobrazený TXT záznam — nebo pošlete správci IT organizace odkaz na administrační portál, aby to udělal sám.',
    'asked_before_every_rule_a_deny_entry_blocks_an_allow_en_e80b3f61' => 'Kontroluje se před každým pravidlem. Záznam zákazu blokuje; záznam povolení přeskočí všechna pravidla včetně vestavěných. Pokud pro jeden pokus platí oba, vyhrává zákaz.',
    'attach_this_to_the_iam_user_whose_access_key_the_stream_7659ba28' => 'Připojte toto k uživateli IAM, jehož přístupový klíč proud používá: smí zapisovat objekty pod prefixem a nic jiného — žádné čtení, výpisy ani mazání.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Zvolte SCIM, pokud poskytovatel posílá data k nám, Google Workspace nebo Entra, pokud je máme stahovat, nebo svůj personální systém — Workday, BambooHR, Rippling, HiBob či Personio — aby lidé přicházeli v den nástupu.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Od příštího pokusu blokace odmítají přihlášení a registrace v tomto prostředí a výzvy vyžadují dodatečné ověření. Chybné pravidlo zablokuje skutečné lidi.',
    'give_it_the_endpoint_or_bucket_and_the_credential_it_ex_4cf81bb7' => 'Zadejte koncový bod nebo bucket a očekávaný přihlašovací údaj; u HTTP sběrače nechte tajný údaj prázdný, aby se vygeneroval klíč HMAC.',
    'let_an_organization_sign_in_with_okta_entra_id_or_googl_cf114dfb' => 'Umožněte organizaci přihlašování přes Okta, Entra ID nebo Google Workspace — nebo pošlete jejímu správci odkaz na administrační portál, aby to nastavil sám.',
    'selected_permissions_count' => 'Vybraná oprávnění: :count',
    'sso_required_organization' => 'Pro organizaci :organization je vyžadováno podnikové SSO. Všechny ostatní způsoby přihlášení jsou blokovány, dokud se tento požadavek nezmění v části „:policy“.',
    'sso_required_environment' => 'Pro toto prostředí je vyžadováno podnikové SSO. Všechny ostatní způsoby přihlášení jsou blokovány, dokud se tento požadavek nezmění v části „:policy“.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Přihlášení uživatele, který :part1, se do starého systému nikdy neposílá. Platí jeho heslo v Cbox ID a starý systém do ověřování nezasahuje.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Pokud je tento koncový bod :part1, uživatelé, kteří ještě nebyli migrováni, se nemohou přihlásit. Již migrovaní uživatelé nejsou ovlivněni.',
    'every_session_in_this_organization_ends_part1_part2_b33262fc' => 'Všechny relace v této organizaci se ukončí — :part1 :part2.',
