    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Nejnovější záznamy v auditní stopě organizace :part1.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 odmítne přihlášení, pokud se hodnota neshoduje přesně. Je rezervována pro toto nastavení, takže ji můžete nyní vložit do :part2 a zde uložit později.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — relace, přístupové klíče, druhé faktory, profily poskytovatelů identity, adresářová data, vydané tokeny, přiřazení rolí i historie auditu zůstanou zachovány. Osobu lze znovu aktivovat.',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Doporučené kroky: :part1, přibližně v tomto pořadí. Každý se označí automaticky, jakmile je skutečně dokončen; nic nemusíte označovat ručně.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Těmito metodami se do této konzole nepřihlašuje. Správci se přihlašují přes Cbox ID na :part2 pomocí jeho přihlašovacích metod.',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Klíč pro správu pro jednoho agenta. Může dělat jen to, co dovolují jeho rozsahy, a vámi vybrané akce čekají na schválení na telefonu nebo zde: :part1.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1 je poskytovatel identity jednoho produktu, účtovaný podle vlastního tarifu. Obsahuje izolovaná :part2 :part3, produkční i testovací, každé s vlastními uživateli, klíči a přihlášením.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Klíč organizace zpřístupňuje samotnou organizaci — projekty, prostředí, tým a klíče — nikoli vnitřek prostředí. Vytvořte jej na kořenové úrovni platformy v části :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Aplikace, které tomuto prostředí důvěřují jako poskytovateli identity SAML. Pro přihlašování již existujícími účty u jiných služeb použijte :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Schvalování se vztahuje na akce API pro správu. Tyto rozsahy obsluhují endpointy, které zatím nejsou akcemi, a proto se vykonávají bez žádosti o schválení: :part1 :part2.',
    'link_an_app_with_the_same_owner_as_the_api_tokens_for_t_0a546071' => 'Propojte aplikaci se stejným vlastníkem jako API. Tokeny pro toto API obsahují role a oprávnění propojené aplikace, proto musí jít o vlastní aplikaci majitele.',
    'not_configured_radar_can_still_block_but_cannot_ask_a_p_0a163809' => 'Není nastaveno — Radar stále může blokovat, ale nemůže člověka požádat, aby prokázal, že je člověk. Označená registrace místo toho potvrzuje e-mailovou adresu.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Vyberte cíl auditní stopy — Splunk, Elastic, Graylog, CEF nebo libovolný sběrač JSON, Datadog či vlastní bucket Amazon S3 nebo Google Cloud Storage.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Vloží klíče přepínačů funkcí zapnutých pro člověka v organizaci, do které se přihlásil, do přístupového tokenu, ID tokenu a UserInfo jako tvrzení `feature_flags`.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Vloží do ID tokenu vše, co UserInfo vrací pro rozsahy aplikace (e-mail, jméno, role, oprávnění, organizace), takže aplikace může při přihlášení vynechat volání UserInfo. Pouze pro aplikaci, která při odhlášení posílá `id_token_hint` metodou POST, nebo ho neposílá vůbec: token v adrese URL se zapisuje do přístupových protokolů.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Vloží ROLE člověka do ID tokenu pod názvem `groups` — právě to hledají Kubernetes, Grafana, Vault a většina starších SaaS. V této konzoli neexistuje nic nazvaného skupina: vytvořte roli s názvem, který aplikace očekává, a objeví se zde.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Zaregistrujte aplikaci, aby se do ní vaši lidé mohli přihlásit účtem, který mají zde. Tímto krokem se Cbox ID stává něčím, co používají.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Tuto ikonu webu nelze použít. Pošlete samotný obrázek jako base64 data: URI (data:image/png;base64,…). Vzdálené URL obrázků se nepřijímají: obrázek na přihlašovací stránce načítá každý návštěvník a externí URL by jeho hostiteli prozradilo, kdo stránku navštěvuje.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Toto logo nelze použít. Pošlete samotný obrázek jako base64 data: URI (data:image/png;base64,…). Vzdálené URL obrázků se nepřijímají: obrázek na přihlašovací stránce načítá každý návštěvník a externí URL by jeho hostiteli prozradilo, kdo stránku navštěvuje.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'Adresa je výstupní uzel Tor, VPN nebo otevřená proxy. Tor se pozná z místního seznamu výstupních uzlů; VPN a proxy vyžadují službu informací o IP adresách, která je uvádí.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'Tlačítko zmizí ze všech přihlašovacích stránek v tomto prostředí, které jej dědí. Přihlašovací údaje zůstanou uložené, takže jej můžete znovu zapnout.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Tlačítko zmizí z přihlašovací stránky této organizace — tlačítko prostředí jej nenahradí. Přihlašovací údaje zůstanou uložené, takže jej můžete znovu zapnout.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'Konzole se přepne na toto prostředí a každá další otevřená stránka bude číst z něj místo ze současného. V žádném z obou se nic nemění.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'Přihlašovací stránka používá identitu vaší organizace: logo, barvy a texty. Změny se zobrazují v živém náhledu a platí pro hostovanou přihlašovací stránku této organizace.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Tento přihlašovací údaj vyžaduje pro tuto akci schválení člověkem, ale není evidován nikdo, kdo by jej mohl dát. Spusťte akci z konzole nebo v konzoli vydejte klíč, aby mohl schválit jeho vlastník.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'Toto prostředí se vrátí ke své výchozí doméně. Každý klient nastavený na současného vydavatele, URL zjišťování konfigurace nebo URL JWKS přestane fungovat, dokud jej nepřenastavíte.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'E-mail se teď nepodařilo odeslat — tato instalace se nemůže spojit s poštovním serverem. Zkuste to později; správce může vaši adresu potvrdit také příkazem `php artisan cbox-id:users:confirm-email`.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Vaše přihlašovací stránka má vaše logo a barvy. Lidé do ní zadávají heslo — měla by vypadat jako vaše, ne naše.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Vytvoření aplikace vydá tajný údaj klienta, který se jednou zobrazí na další obrazovce — přihlašuje jako tato aplikace, dokud neproběhne rotace.',
    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'Při registraci aplikace se vytvoří tajný údaj klienta, který se zobrazí pouze jednou na další obrazovce. Umožňuje přihlášení jménem této aplikace, dokud jej nenahradíte novým.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'V tomto projektu není jiné prostředí, které spravujete. Přidejte jej do projektu nebo si vyžádejte přístup a objeví se zde.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Tato aplikace patří organizaci a organizace existuje pouze v jednom prostředí. Stáhněte její předlohu a zaregistrujte ji v druhém prostředí pod organizací, ke které tam patří.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Tato aplikace se zaregistrovala sama, takže nepatří mezi vlastní aplikace tohoto prostředí. Stejným způsobem se může zaregistrovat i v druhém prostředí.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Tato aplikace se přihlašuje vlastními klíči a každé prostředí by mělo mít své. Stáhněte její předlohu a zaregistrujte ji v druhém prostředí s tamní sadou klíčů.',
    'app_keys_unavailable_organization_switch' => 'Aplikace, která vás sem přesměrovala, nenabízí klíče API pro organizaci :organization. Zkuste jinou organizaci nebo kontaktujte podporu aplikace.',
    'app_keys_unavailable_organization' => 'Aplikace, která vás sem přesměrovala, nenabízí klíče API pro organizaci :organization. Kontaktujte podporu aplikace.',
    'app_keys_unavailable_switch' => 'Aplikace, která vás sem přesměrovala, nenabízí klíče API. Zkuste jinou organizaci nebo kontaktujte podporu aplikace.',
    'app_keys_unavailable' => 'Aplikace, která vás sem přesměrovala, nenabízí klíče API. Kontaktujte podporu aplikace.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Připojte se jednou na kořenové úrovni platformy místo zvlášť pro každé prostředí. Agent přihlášený vaším jménem má přístup k organizaci, všem jejím prostředím, která spravujete, i vašemu účtu. Nástroj prostředí přijímá argument :part1 :part2 a REST API hlavičku :part3 určující, kde se má jednat. Agent může dělat to co vy v rozsahu vašeho povolení a každá kritická akce čeká na schválení na vašem zařízení.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Každá organizace osobě přiřadí jednu roli typu :part1, která určuje možnosti správy, a libovolný počet rolí typu :part2, které určují možnosti v aplikacích.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Prostředí „:part1“ bylo vytvořeno. V nastavení domén prostředí přidejte :part2 pro ověření pomocí DNS. Neověřená doména nemůže být vydavatelem prostředí.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Prostředí patří pod projekt a projekt pod :part1 :part2 :part3. Začněte tam a uvidíte všechny prostředky organizace. Dva druhy záznamů organizaci nikdy nemají: :part4 je prostředí samotné instalace, kde jsou provozovatelé a členové organizací; prostředí označené :part5 :part6 nemá projekt, takže se neúčtuje a žádná organizace k němu nemá přístup. Nejde o chyby k opravě na této obrazovce a nelze zde měnit jejich přiřazení.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Všechny způsoby přihlášení do :part1, jejich stav a místo nastavení. Organizace mohou pravidla zpřísnit: :part2 :part3.',
