    'hand_it_to_part1_over_a_channel_you_trust_we_never_stor_205e825e' => 'Předejte heslo uživateli :part1 důvěryhodným kanálem. Nikdy ho neukládáme v čitelné podobě.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'V pořadí, v jakém je lidé vidí. Vypnutí poskytovatele prostředí zde pouze odstraní tlačítko z této stránky; nezabrání přihlášení přes něj jinde. Chcete-li svého poskytovatele jako jedinou možnost, vyžadujte SSO v :part1 :part2.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Dotčené osoby (:part1) se již nemohou přihlásit k této organizaci a aplikace, které na ní závisejí, je přestanou ověřovat. Podřízené organizace se nepozastaví. Organizaci zde můžete znovu aktivovat.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Klíče začínají tímto prefixem, takže klíč nalezený v protokolu určuje aplikaci: :part1 :part2. Použijte 2–16 malých písmen nebo číslic a poté :part3 nebo :part4 :part5, jedinečné v tomto prostředí. Nastavením zapnete klíče; vymazání zastaví tvorbu nových, ale existující fungují do zneplatnění.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Nikdo v této organizaci nevytvořil klíč pro její aplikace. Lidé si tvoří vlastní v části Můj účet pro aplikaci, která v Nastavení zapne klíče API členů: :part1.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Vložte celý soubor JSON s klíčem servisního účtu, kterému je pro bucket udělena role roles/storage.objectCreator. Ukládá se šifrovaně a již se nezobrazí. :part1',
