    'connected_part1_part2_part3_part4_a093c4a3' => 'Připojeno: :part1 :part2 :part3 :part4',
    'add_this_dns_part1_record_at_your_domain_then_verify_it_3d494578' => 'Přidejte tento DNS záznam typu :part1 ke své doméně a poté spusťte ověření. Tím prokážete, že ovládáte doménu :part2.',
    'confirm_your_email_address_part1_to_make_changes_in_the_7b9d8809' => 'Potvrďte svou e-mailovou adresu :part1, abyste mohli provádět změny v konzoli.',
