    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Přihlaste se do aplikace jako :part1 a podívejte se, co tato osoba vidí. Aplikace ví, že jste to vy, a auditní protokol organizace zaznamená, kdo to provedl, kdy a proč.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Když se někdo přihlašuje a platí :part1, jeho e-mail a heslo se odešlou na tento endpoint. Pokud endpoint přihlášení přijme, osoba se vytvoří zde a údaje se tam již znovu neposílají.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Potřebujete pomoc s některým krokem? Každá stránka konzole má vedle názvu ikonu :part1 :part2 :part3 s krátkým vysvětlením a odkazem na úplný návod.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Zde je dostupné pouze pozastavení, které lze vrátit zpět. Tato obrazovka organizaci nemaže ani trvale neodstraňuje její data. Instalace obsahuje i prostředí bez organizace: kořen platformy a nepřiřazené pozůstatky. Oba typy jsou označeny v :part1 :part2.',
    'agent_revoke_descendant_count' => 'Agent okamžitě přestane fungovat. Odvolají se i klíče, které vydal (celkem: :count). Tuto akci nelze vrátit zpět.',
