    'to_answer_a_right_to_erasure_request_use_part1_at_the_f_536cbf09' => 'K vyřízení žádosti o uplatnění práva na výmaz použijte místo toho možnost „:part1“ ve spodní části této stránky.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'Kódy SMS pro :part1 přestanou fungovat. Ověřovací aplikace, přístupové klíče a kódy pro obnovení zůstávají beze změny. Pokud byl telefon jediným druhým faktorem, bude účet do nové registrace chráněn jen heslem.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Tím je seznam dokončen. Odteď se do konzole budete především vracet pro kontrolu. Pravidelně se vyplatí sledovat tyto dvě oblasti: :part1 :part2 :part3 a :part4 :part5 :part6.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'E-mailové domény nárokované vašimi organizacemi. Ověřená doména směruje všechny osoby s adresou v této doméně na připojení organizace: :part1 :part2. Každá doména se ověřuje na stránce své organizace.',
